# Coroutines v2 · Phần 3 · FP Xử lý flow (Deep Dive: "Flow processing", trang PDF 318–344) + sim coroutines.flatmap và coroutines.combine.

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    # ---------------- sim coroutines.combine ----------------
    m = lambda k, vi, en=None: a('m.combine.' + k, vi, en)
    m('title', 'Gộp hai flow: merge, zip, combine', 'Combining two flows: merge, zip, combine')
    m('overview', 'Cùng hai flow như sách: flow1 phát A, B, C (mỗi phần tử sau 400 ms), flow2 phát 1, 2, 3, 4 (mỗi phần tử sau 1000 ms). Chọn cách gộp rồi bấm Step: xem mỗi kết quả ra lúc nào và vì sao.', 'The same two flows as the book: flow1 emits A, B, C (each after 400 ms), flow2 emits 1, 2, 3, 4 (each after 1000 ms). Pick a way to combine them and press Step: see when each result comes out and why.')
    m('wrapup', '`merge` chuyển nguyên mọi phần tử, không chờ ai. `zip` ghép cặp theo thứ tự, mỗi phần tử chỉ dùng một lần, và dừng khi một flow hết (phần tử lẻ bị bỏ). `combine` luôn ghép giá trị MỚI NHẤT của mỗi bên, phát lại mỗi khi một bên đổi, và chạy tới khi cả hai flow xong.', '`merge` passes every element through, waiting for nobody. `zip` pairs elements in order, uses each element once, and stops when one flow ends (unpaired elements are dropped). `combine` always pairs the LATEST value of each side, emits again whenever either side changes, and runs until both flows finish.')
    m('simp.1', 'Thời điểm khớp output in trong sách. Thời điểm phát của flow1 trong zip (400/1400/2400) suy từ mã `zipImpl` của kotlinx.coroutines: flow1 được collect tuần tự trong coroutine của zip, flow2 chạy trong `produce` với channel rendezvous.', 'Timings match the output printed in the book. flow1\'s emission times under zip (400/1400/2400) are derived from kotlinx.coroutines\' `zipImpl` code: flow1 is collected sequentially in zip\'s coroutine, flow2 runs in a `produce` with a rendezvous channel.')
    m('ctl.hint', 'Đổi cách gộp và so cột "kết quả" cùng thời điểm kết thúc.', 'Switch the combining method and compare the "result" row and the end time.')
    m('ctl.mode', 'Cách gộp', 'Combining method')
    for k in ['merge', 'zip', 'combine']:
        m('ctl.mode.' + k, k); m('scope.' + k, k)
    m('diagramTitle', 'Hai flow nguồn và flow kết quả theo thời gian', 'Two source flows and the result flow over time')
    m('diagramDesc', 'Hàng flow1, flow2 và hàng kết quả', 'Rows for flow1, flow2 and the result')
    m('n.f1', 'flow1 (A B C)', 'flow1 (A B C)')
    m('n.f2', 'flow2 (1 2 3 4)', 'flow2 (1 2 3 4)')
    m('n.out', 'Kết quả (collect)', 'Result (collect)')
    m('col', 'Cách gộp', 'Method')
    m('axis', 'ms (thời gian của mã) →', 'ms (code time) →')
    m('met.out', 'Kết quả đã phát', 'Results emitted')
    m('bar.run', 'flow đang chạy (đang delay hoặc phát)', 'flow running (delaying or emitting)')
    m('bar.wait', 'đứng chờ', 'waiting')
    m('lbl.waitPair', 'chờ cặp', 'waiting for a pair')
    S = [
        ('start', 'Bắt đầu collect', 'Collection starts', 'Thao tác terminal khởi động cả hai flow nguồn.', 'The terminal operation starts both source flows.'),
        ('pass', 'Chuyển tiếp {v}', 'Pass {v} through', '`merge` không biến đổi gì: phần tử {v} từ bất kỳ flow nào đến là chuyển ngay xuống collect.', '`merge` transforms nothing: element {v}, from whichever flow, goes straight down to collect.'),
        ('zwait', '{v} chờ cặp', '{v} waits for a pair', 'zip nhận {v} từ flow1 rồi gọi `receive` trên channel của flow2. Chưa có số nào nên coroutine của zip treo ở đó, và flow1 cũng đứng (nó đang được collect trong chính coroutine này).', 'zip receives {v} from flow1 then calls `receive` on flow2\'s channel. No number is there yet, so zip\'s coroutine suspends, and flow1 stops too (it is being collected in that very coroutine).'),
        ('zpair', 'Ghép cặp {r}', 'Pair {r}', 'flow2 phát {v}, gặp phần tử đang chờ của flow1, zip phát {r}. Xong lượt này flow1 mới chạy tiếp (lại delay 400 ms).', 'flow2 emits {v}, meets flow1\'s waiting element, and zip emits {r}. Only after that does flow1 continue (another 400 ms delay).'),
        ('zend', 'flow1 hết: zip kết thúc, hủy flow2', 'flow1 is done: zip ends and cancels flow2', 'flow1 không còn phần tử nên không thể có cặp nào nữa. zip kết thúc và hủy flow2; số 4 không bao giờ được phát.', 'flow1 has no more elements, so no more pairs are possible. zip ends and cancels flow2; the number 4 is never emitted.'),
        ('cfirst', '{v} đến, chưa có cặp', '{v} arrives, no pair yet', '`combine` lưu {v} làm giá trị mới nhất của flow1. flow2 chưa phát gì nên chưa thể ghép.', '`combine` stores {v} as flow1\'s latest value. flow2 has not emitted yet, so nothing can be paired.'),
        ('creplace', '{v} thay giá trị cũ', '{v} replaces the old value', 'Giá trị mới thay giá trị trước. A chưa từng được ghép và sẽ không bao giờ xuất hiện trong kết quả.', 'The new value replaces the previous one. A was never paired and will never appear in the result.'),
        ('cpair', 'Phát {r}', 'Emit {r}', 'Một bên đổi giá trị nên `combine` ghép hai giá trị mới nhất và phát {r}.', 'One side changed, so `combine` pairs the two latest values and emits {r}.'),
        ('end', 'Cả hai flow xong', 'Both flows are done', 'flow kết quả hoàn tất khi cả hai nguồn hoàn tất.', 'The result flow completes when both sources complete.'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('start.merge', 'merge chạy mỗi flow trong một coroutine riêng (dựa trên channelFlow).', 'merge runs each flow in its own coroutine (built on channelFlow).'),
        ('start.zip', 'zip collect flow1 ngay trong coroutine của nó; flow2 chạy trong `produce` (channel rendezvous).', 'zip collects flow1 in its own coroutine; flow2 runs in a `produce` (rendezvous channel).'),
        ('start.combine', 'combine collect hai flow độc lập và giữ giá trị mới nhất của mỗi bên.', 'combine collects both flows independently and keeps each side\'s latest value.'),
        ('mergeIndep', 'Phần tử của flow này không chờ flow kia.', 'Elements of one flow do not wait for the other.'),
        ('zipSeq', 'Để ý: trong zip, B đến lúc 1400 chứ không phải 800. flow1 bị "kéo" theo nhịp của flow2.', 'Notice: under zip, B arrives at 1400, not 800. flow1 is "dragged" along at flow2\'s pace.'),
        ('zipLost', 'Phần tử không có cặp bị mất. Nếu cần mọi phần tử, zip là lựa chọn sai.', 'Unpaired elements are lost. If you need every element, zip is the wrong choice.'),
        ('replace', 'combine chỉ quan tâm trạng thái mới nhất, nên phần tử trung gian có thể bị bỏ qua.', 'combine only cares about the latest state, so intermediate elements can be skipped.')]:
        m('co.' + k, vi, en)
    a('cap.combine', 'Ba hàng theo thời gian: flow1, flow2 và kết quả. Hình thoi là một phần tử được phát; thanh viền đứt là đang chờ. Nhãn ở hàng kết quả chỉ hiện cho bước hiện tại.', 'Three rows over time: flow1, flow2 and the result. A diamond is an emitted element; a dashed bar is waiting. Labels on the result row appear only for the current step.')

    # ---------------- sim coroutines.flatmap ----------------
    m = lambda k, vi, en=None: a('m.flatmap.' + k, vi, en)
    m('title', 'flatMapConcat, flatMapMerge, flatMapLatest', 'flatMapConcat, flatMapMerge, flatMapLatest')
    m('overview', 'Flow ngoài phát A, B, C. Mỗi phần tử tạo một flow con `flowFrom(x)` phát 1_x, 2_x, 3_x cách nhau 1 giây. Chọn biến thể flatMap rồi bấm Step: các flow con chạy nối tiếp, song song, hay bị hủy?', 'The outer flow emits A, B, C. Each element creates a child flow `flowFrom(x)` that emits 1_x, 2_x, 3_x one second apart. Pick a flatMap variant and press Step: do the child flows run one after another, in parallel, or get cancelled?')
    m('wrapup', 'Concat: nối tiếp, giữ thứ tự, chậm (9 s). Merge: song song, nhanh (3 s), thứ tự xen kẽ, tối đa `concurrency` flow con cùng lúc (mặc định 16). Latest: phần tử mới tới thì hủy flow con cũ, chỉ kết quả của phần tử MỚI NHẤT sống sót (hợp với tìm kiếm khi gõ).', 'Concat: sequential, ordered, slow (9 s). Merge: parallel, fast (3 s), interleaved order, at most `concurrency` children at once (default 16). Latest: a new element cancels the old child flow, only the result of the LATEST element survives (fits search-as-you-type).')
    m('simp.1', 'Thời điểm khớp output in trong sách cho cả bốn chế độ. Chế độ "latest" dùng ví dụ có `onEach { delay(1200) }` ở flow ngoài.', 'Timings match the output printed in the book for all four modes. The "latest" mode uses the example with `onEach { delay(1200) }` on the outer flow.')
    m('ctl.hint', 'Đổi biến thể và so thời điểm kết thúc cùng số flow con chạy cùng lúc.', 'Switch the variant and compare the end time and the number of children running at once.')
    m('ctl.mode', 'Biến thể', 'Variant')
    for k, lbl in [('concat', 'flatMapConcat'), ('merge', 'flatMapMerge'), ('merge2', 'flatMapMerge(concurrency = 2)'), ('latest', 'flatMapLatest')]:
        m('ctl.mode.' + k, lbl); m('scope.' + k, lbl)
    m('diagramTitle', 'Ba flow con và flow kết quả theo thời gian', 'Three child flows and the result flow over time')
    m('diagramDesc', 'Hàng flow con A, B, C và hàng kết quả', 'Rows for child flows A, B, C and the result')
    for x in 'ABC':
        m('n.' + x, 'flowFrom("%s")' % x)
    m('n.out', 'Kết quả (collect)', 'Result (collect)')
    m('col', 'Biến thể', 'Variant')
    m('axis', 'ms (thời gian của mã) →', 'ms (code time) →')
    m('met.out', 'Kết quả đã phát', 'Results emitted')
    m('met.act', 'Flow con đang chạy', 'Children running')
    m('bar.run', 'flow con đang chạy', 'child flow running')
    m('bar.wait', 'xếp hàng, chưa được chạy', 'queued, not started yet')
    m('lbl.queued', 'xếp hàng', 'queued')
    S = [
        ('startQ', 'A chạy; B và C xếp hàng', 'A runs; B and C queue', '`flatMapConcat` tạo `flowFrom("A")` và collect nó tới hết. B và C đã có nhưng phải chờ.', '`flatMapConcat` creates `flowFrom("A")` and collects it to the end. B and C are already there but must wait.'),
        ('startAll', 'A, B, C cùng chạy', 'A, B, C all run', '`flatMapMerge` collect mỗi flow con trong một coroutine riêng, nên cả ba chạy song song.', '`flatMapMerge` collects each child flow in its own coroutine, so all three run in parallel.'),
        ('startQ2', 'A và B chạy; C xếp hàng', 'A and B run; C queues', 'Giới hạn `concurrency = 2`: chỉ hai flow con chạy cùng lúc, C chờ một chỗ trống.', 'The `concurrency = 2` limit: only two children run at once, C waits for a free slot.'),
        ('emit', 'Phát {v}', 'Emit {v}', 'Flow con của {x} phát {v}, đi thẳng xuống collect.', 'The child flow of {x} emits {v}, which goes straight down to collect.'),
        ('next', '{x} bắt đầu sau khi flow trước xong', '{x} starts after the previous flow finishes', 'Flow con trước đã hoàn tất, giờ mới tới lượt flow của {x}.', 'The previous child flow has completed; only now is it {x}\'s turn.'),
        ('slot', 'Có chỗ trống: {x} bắt đầu', 'A slot frees up: {x} starts', 'A và B đã xong nên C được chạy. Kết quả của C ra muộn 3 giây so với chế độ không giới hạn.', 'A and B are done, so C may run. C\'s results come out 3 seconds later than with no limit.'),
        ('outer', 'A đến (sau 1,2 s): flowFrom("A") chạy', 'A arrives (after 1.2 s): flowFrom("A") runs', 'Flow ngoài có `delay(1200)` trước mỗi phần tử.', 'The outer flow has `delay(1200)` before each element.'),
        ('switch', '{x} đến: hủy flow con cũ', '{x} arrives: the old child is cancelled', '`flatMapLatest` hủy flow con đang chạy và bắt đầu `flowFrom("{x}")`. Những gì flow cũ chưa kịp phát sẽ không bao giờ tới.', '`flatMapLatest` cancels the running child and starts `flowFrom("{x}")`. Whatever the old flow had not emitted yet will never arrive.'),
        ('end', 'Mọi flow con xong', 'All child flows are done', 'Flow kết quả hoàn tất khi flow ngoài và mọi flow con đều xong.', 'The result flow completes when the outer flow and every child flow are done.'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('concat', 'Concat = từng flow con một, giữ nguyên thứ tự.', 'Concat = one child flow at a time, order preserved.'),
        ('merge', 'Merge = song song. Thứ tự kết quả phụ thuộc thời gian, không phụ thuộc thứ tự A, B, C.', 'Merge = parallel. The result order depends on timing, not on the order A, B, C.'),
        ('limit', '`concurrency` mặc định là 16. Có 100 phần tử thì chỉ 16 flow con chạy cùng lúc, số còn lại xếp hàng.', 'The default `concurrency` is 16. With 100 elements, only 16 children run at once and the rest queue.'),
        ('latest', 'Hủy là chuyện bình thường ở đây: 2_A, 3_A không bao giờ xuất hiện.', 'Cancellation is normal here: 2_A and 3_A never appear.'),
        ('end.concat', 'Xong sau 9 giây.', 'Done after 9 seconds.'),
        ('end.merge', 'Xong sau 3 giây.', 'Done after 3 seconds.'),
        ('end.merge2', 'Xong sau 6 giây.', 'Done after 6 seconds.'),
        ('end.latest', 'Xong sau 6,6 giây; chỉ C chạy trọn.', 'Done after 6.6 seconds; only C ran to completion.')]:
        m('co.' + k, vi, en)
    a('cap.flatmap', 'Bốn hàng theo thời gian: ba flow con và kết quả. Thanh liền = flow con đang chạy; thanh viền đứt = đang xếp hàng; thanh dừng giữa chừng = bị hủy. Hình thoi là một phần tử được phát.', 'Four rows over time: three child flows and the result. A solid bar = a child flow running; a dashed bar = queued; a bar that stops midway = cancelled. A diamond is an emitted element.')

    # ---------------- chương FP ----------------
    C = 'fp'
    a(C + '.title', 'Xử lý flow: map, filter, scan, merge/zip/combine, flatMap, retry, distinct', 'Flow processing: map, filter, scan, merge/zip/combine, flatMap, retry, distinct')
    a(C + '.essence',
      'Giữa nơi tạo flow và thao tác terminal là các toán tử xử lý. Chúng giống các hàm xử lý collection, khác ở chỗ phần tử trải ra theo thời gian. Hầu hết chỉ là `flow { collect { … emit(…) } }`: `map`, `filter`, `take`, `drop`, `scan`, `distinctUntilChanged` đều viết được trong vài dòng.\n'
      'Phần khó nằm ở chỗ thời gian quan trọng. Gộp hai flow: `merge` chuyển tiếp mọi phần tử, `zip` ghép cặp một-một (bỏ phần tử lẻ), `combine` ghép giá trị mới nhất mỗi khi một bên đổi. Mỗi phần tử sinh một flow con: `flatMapConcat` chạy lần lượt, `flatMapMerge` chạy song song (tối đa `concurrency`, mặc định 16), `flatMapLatest` hủy flow con cũ khi có phần tử mới.\n'
      '`retry` collect lại flow phía trên từ đầu khi có exception (flow lạnh nên chạy lại được, và các phần tử đầu sẽ được phát LẠI). Terminal (`collect`, `first`, `count`, `fold`, `reduce`) đều là hàm suspend dựa trên `collect`; mỗi lần gọi là một lần chạy lại flow lạnh.',
      'Between creating a flow and the terminal operation come processing operators. They resemble collection-processing functions, except elements are spread over time. Most are just `flow { collect { … emit(…) } }`: `map`, `filter`, `take`, `drop`, `scan`, `distinctUntilChanged` each fit in a few lines.\n'
      'The hard part is that time matters. Combining two flows: `merge` passes every element through, `zip` pairs one-to-one (dropping leftovers), `combine` pairs the latest values whenever either side changes. When each element spawns a child flow: `flatMapConcat` runs them one by one, `flatMapMerge` runs them in parallel (at most `concurrency`, default 16), `flatMapLatest` cancels the old child when a new element arrives.\n'
      '`retry` re-collects the upstream flow from the start on an exception (it is cold, so it can rerun, and the early elements are emitted AGAIN). Terminal operations (`collect`, `first`, `count`, `fold`, `reduce`) are suspending functions built on `collect`; each call reruns a cold flow.')
    a(C + '.sim.coroutines.flatmap', 'flatMap: nối tiếp, song song, mới nhất', 'flatMap: sequential, parallel, latest')
    a(C + '.sim.coroutines.combine', 'merge, zip, combine', 'merge, zip, combine')
    a(C + '.goal.g1', 'Đã thấy flatMapConcat chờ flow con trước xong', 'Saw flatMapConcat wait for the previous child to finish')
    a(C + '.goal.g2', 'Đã chạy một biến thể flatMap tới cuối', 'Ran a flatMap variant to the end')

    S = 'recap'
    a(C + '.sec.%s.title' % S, 'Ôn nhanh chương trước', 'Quick review of the previous chapter')
    B(C, S, 1, 'ask', 'Trong `flow.catch { … }.map { parse(it) }`, lỗi của `parse` có bị bắt không? Vì sao?', 'In `flow.catch { … }.map { parse(it) }`, is an error from `parse` caught? Why?')
    B(C, S, 1, 'ans', 'Không. `catch` chỉ bắt lỗi từ các tầng phía TRÊN nó; `map` nằm phía dưới. Chương này nhìn kỹ từng tầng đó: mỗi toán tử là một flow mới collect flow phía trên.', 'No. `catch` only catches errors from stages ABOVE it; `map` is below. This chapter looks closely at those stages: each operator is a new flow that collects the flow above.')

    S = 'basics'
    a(C + '.sec.%s.title' % S, 'map, filter, take, drop: toán tử là một flow collect flow khác', 'map, filter, take, drop: an operator is a flow collecting another flow')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Hình dung flow là đường ống mà giá trị chảy qua; trên đường chúng có thể bị bỏ, nhân lên, biến đổi hay gộp lại. Các hàm này giống hệt hàm xử lý collection (`map`, `filter`…), vì chúng biểu diễn cùng khái niệm, chỉ khác là phần tử của flow trải ra theo thời gian. `map` biến đổi từng phần tử; `filter` chỉ giữ phần tử thỏa điều kiện; `take(n)` lấy n phần tử đầu rồi DỪNG flow phía trên; `drop(n)` bỏ n phần tử đầu.', 'Picture a flow as a pipe values flow through; on the way they can be dropped, multiplied, transformed or combined. These functions mirror collection-processing functions (`map`, `filter`…), because they express the same concepts, except a flow\'s elements are spread over time. `map` transforms each element; `filter` keeps only matching elements; `take(n)` takes the first n elements and then STOPS the upstream; `drop(n)` skips the first n.')
    B(C, S, 2, 'kt', 'flowOf(1, 2, 3).map { it * it }.collect { print(it) }        // 149\n(1..10).asFlow().filter { it <= 5 }.filter { it % 2 == 0 }  // [2, 4]\n(\'A\'..\'Z\').asFlow().take(5)                                // ABCDE\n(\'A\'..\'Z\').asFlow().drop(20)                               // UVWXYZ\n\n// hiện thực (giản lược, gần với bản thật trong kotlinx.coroutines)\nfun <T, R> Flow<T>.map(transform: suspend (T) -> R): Flow<R> = flow {\n    collect { value -> emit(transform(value)) }\n}\nfun <T> Flow<T>.filter(predicate: suspend (T) -> Boolean): Flow<T> = flow {\n    collect { value -> if (predicate(value)) emit(value) }\n}', 'flowOf(1, 2, 3).map { it * it }.collect { print(it) }        // 149\n(1..10).asFlow().filter { it <= 5 }.filter { it % 2 == 0 }  // [2, 4]\n(\'A\'..\'Z\').asFlow().take(5)                                // ABCDE\n(\'A\'..\'Z\').asFlow().drop(20)                               // UVWXYZ\n\n// implementations (simplified, close to the real ones in kotlinx.coroutines)\nfun <T, R> Flow<T>.map(transform: suspend (T) -> R): Flow<R> = flow {\n    collect { value -> emit(transform(value)) }\n}\nfun <T> Flow<T>.filter(predicate: suspend (T) -> Boolean): Flow<T> = flow {\n    collect { value -> if (predicate(value)) emit(value) }\n}')
    B(C, S, 3, 'p', 'Dùng thường gặp: `map` để mở gói hay đổi kiểu (`User` → `UserJson`, mã phím → `UserAction`); `filter` để bỏ phần tử không quan tâm (hành động không hợp lệ). Thứ tự quan trọng: `filter { isValid(it.code) }.map { toAction(it.code) }` lọc trước rồi mới đổi kiểu, đỡ tốn công biến đổi phần tử sẽ bị bỏ.', 'Typical uses: `map` to unpack or convert types (`User` → `UserJson`, key code → `UserAction`); `filter` to drop elements you do not care about (invalid actions). Order matters: `filter { isValid(it.code) }.map { toAction(it.code) }` filters first, then converts, avoiding work on elements that will be dropped.')

    S = 'trace'
    a(C + '.sec.%s.title' % S, 'Lần theo một chuỗi toán tử: không có phép màu', 'Tracing an operator chain: no magic')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Thay `map` và `flowOf` bằng thân của chúng, ta được đoạn mã chỉ gồm lambda lồng nhau. Đánh số 1–8 và theo luồng điều khiển, bạn sẽ thấy mọi toán tử khác chạy cùng một kiểu.', 'Replace `map` and `flowOf` with their bodies and you get code made only of nested lambdas. Number them 1–8 and follow the control flow, and you will see every other operator runs the same way.')
    B(C, S, 2, 'kt', 'flowOf(\'a\', \'b\').map { it.uppercase() }.collect { print(it) }   // AB\n\n// sau khi thay thân hàm vào (đánh số theo sách):\nflow map@{                                            // 1\n    flow flowOf@{                                     // 2\n        for (element in arrayOf(\'a\', \'b\')) {          // 3\n            this@flowOf.emit(element)                 // 4\n        }\n    }.collect { value ->                              // 5\n        this@map.emit(value.uppercase())              // 6\n    }\n}.collect {                                           // 7\n    print(it)                                         // 8\n}', 'flowOf(\'a\', \'b\').map { it.uppercase() }.collect { print(it) }   // AB\n\n// after inlining the function bodies (numbered as in the book):\nflow map@{                                            // 1\n    flow flowOf@{                                     // 2\n        for (element in arrayOf(\'a\', \'b\')) {          // 3\n            this@flowOf.emit(element)                 // 4\n        }\n    }.collect { value ->                              // 5\n        this@map.emit(value.uppercase())              // 6\n    }\n}.collect {                                           // 7\n    print(it)                                         // 8\n}')
    B(C, S, 3, 'predict', 'Khi \'a\' được `emit` ở dòng 4, dòng nào chạy kế tiếp, và dòng 4 trả về lúc nào?', 'When \'a\' is emitted at line 4, which line runs next, and when does line 4 return?')
    B(C, S, 3, 'ans', 'Dòng 4 gọi lambda ở 5, lambda này biến \'a\' thành \'A\' và gọi `emit` ở 6, tức gọi lambda ở 7, in ra ở 8. Rồi lần lượt trở về: 7 xong → 6 trả về → 5 xong → 4 trả về, vòng lặp ở 3 mới lấy \'b\'. Một phần tử đi trọn đường ống rồi phần tử sau mới bắt đầu (đúng như sim lanes ở chương FL).', 'Line 4 calls the lambda at 5, which turns \'a\' into \'A\' and calls `emit` at 6, i.e. calls the lambda at 7, which prints at 8. Then everything returns in turn: 7 ends → 6 returns → 5 ends → 4 returns, and only then does the loop at 3 take \'b\'. One element travels the whole pipe before the next starts (just like the lanes sim in chapter FL).')

    S = 'foldscan'
    a(C + '.sec.%s.title' % S, 'fold và scan: gom giá trị theo thời gian', 'fold and scan: accumulating values over time')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', '`fold(initial) { acc, v -> … }` gom mọi phần tử thành một giá trị: bắt đầu từ `initial`, lần lượt kết hợp với từng phần tử. Với flow, `fold` là thao tác TERMINAL: nó suspend tới khi flow xong (như `collect`). `scan` là bản trung gian: phát `initial` ngay, rồi phát giá trị tích lũy sau MỖI phần tử. Đây là thứ ta cần khi có một dòng "thay đổi" và muốn một dòng "trạng thái hiện tại".', '`fold(initial) { acc, v -> … }` accumulates every element into one value: start from `initial`, then combine with each element in turn. On a flow, `fold` is a TERMINAL operation: it suspends until the flow completes (like `collect`). `scan` is the intermediate version: it emits `initial` right away, then emits the accumulated value after EACH element. That is what you need when you have a stream of "changes" and want a stream of "current state".')
    B(C, S, 2, 'kt', 'flowOf(1, 2, 3, 4).onEach { delay(1000) }.fold(0) { acc, i -> acc + i }   // (4 s) 10\n\nflowOf(1, 2, 3, 4).onEach { delay(1000) }\n    .scan(0) { acc, v -> acc + v }\n    .collect { println(it) }      // 0, (1 s) 1, (1 s) 3, (1 s) 6, (1 s) 10\n\nfun <T, R> Flow<T>.scan(initial: R, operation: suspend (R, T) -> R): Flow<R> = flow {\n    var accumulator = initial\n    emit(accumulator)\n    collect { value -> accumulator = operation(accumulator, value); emit(accumulator) }\n}\n\n// dòng thay đổi → dòng trạng thái\nval userStateFlow: Flow<User> = userChangesFlow.scan(user) { u, change -> u.withChange(change) }\nval messagesListFlow: Flow<List<Message>> = messagesFlow.scan(messages) { acc, msg -> acc + msg }', 'flowOf(1, 2, 3, 4).onEach { delay(1000) }.fold(0) { acc, i -> acc + i }   // (4 s) 10\n\nflowOf(1, 2, 3, 4).onEach { delay(1000) }\n    .scan(0) { acc, v -> acc + v }\n    .collect { println(it) }      // 0, (1 s) 1, (1 s) 3, (1 s) 6, (1 s) 10\n\nfun <T, R> Flow<T>.scan(initial: R, operation: suspend (R, T) -> R): Flow<R> = flow {\n    var accumulator = initial\n    emit(accumulator)\n    collect { value -> accumulator = operation(accumulator, value); emit(accumulator) }\n}\n\n// a stream of changes → a stream of state\nval userStateFlow: Flow<User> = userChangesFlow.scan(user) { u, change -> u.withChange(change) }\nval messagesListFlow: Flow<List<Message>> = messagesFlow.scan(messages) { acc, msg -> acc + msg }')
    B(C, S, 3, 'note', 'Mẫu `scan` chính là "reducer" trong kiến trúc MVI/UDF: `intents.scan(initialState) { state, intent -> reduce(state, intent) }`. Biến trạng thái nằm trong toán tử, không phải một biến chung bên ngoài, nên không có race condition giữa các lần collect.', 'The `scan` pattern is exactly the "reducer" of MVI/UDF architectures: `intents.scan(initialState) { state, intent -> reduce(state, intent) }`. The state variable lives inside the operator, not in a shared outer variable, so there is no race between collections.')
    B(C, S, 3, 'kind', 'android')

    S = 'combine'
    a(C + '.sec.%s.title' % S, 'merge, zip, combine: gộp hai flow', 'merge, zip, combine: combining two flows')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', '`merge(f1, f2)` gộp phần tử của hai flow thành một, không biến đổi gì, và phần tử của flow này KHÔNG chờ flow kia. Ví dụ của sách: `ints` có `delay(1000)` mỗi phần tử, `doubles` không; output là 0.1, 0.2, 0.3 trước, rồi mỗi giây 1, 2, 3. Dùng khi nhiều nguồn sự kiện dẫn tới cùng một hành động: `merge(userSentMessages, messagesNotifications).onEach { displayMessage(it) }.launchIn(scope)`.', '`merge(f1, f2)` combines the elements of two flows into one, unchanged, and elements of one flow do NOT wait for the other. The book\'s example: `ints` has `delay(1000)` per element, `doubles` does not; the output is 0.1, 0.2, 0.3 first, then 1, 2, 3 one per second. Use it when several event sources lead to the same action: `merge(userSentMessages, messagesNotifications).onEach { displayMessage(it) }.launchIn(scope)`.')
    B(C, S, 2, 'p', '`zip` ghép cặp: mỗi phần tử chỉ thuộc một cặp, nên phải chờ cặp của mình; phần tử lẻ bị mất, và khi một flow xong thì kết quả cũng xong (flow kia bị hủy). Tác giả ví nó với điệu polonaise: hàng đôi tách ra rồi gặp lại nhau. Chi tiết cơ chế (đọc từ mã `zipImpl`): zip collect flow thứ nhất ngay trong coroutine của nó, còn flow thứ hai chạy trong `produce` với channel rendezvous; mỗi phần tử của flow thứ nhất gọi `receive` và treo tới khi flow thứ hai đưa phần tử tới. Vì vậy flow thứ nhất bị kéo theo nhịp của flow thứ hai ([[src:kx-src-combine]], [[src:kx-zip]]).', '`zip` makes pairs: each element belongs to exactly one pair, so it must wait for its partner; leftover elements are lost, and when one flow ends the result ends too (the other is cancelled). The author compares it to the polonaise: pairs split and meet again. Mechanism detail (read from the `zipImpl` code): zip collects the first flow in its own coroutine, while the second flow runs in a `produce` with a rendezvous channel; each element of the first flow calls `receive` and suspends until the second flow delivers one. So the first flow is dragged along at the second flow\'s pace ([[src:kx-src-combine]], [[src:kx-zip]]).')
    B(C, S, 3, 'p', '`combine` cũng ghép cặp và cũng chờ bên chậm cho cặp đầu tiên. Sau đó mỗi phần tử mới THAY phần tử trước của bên mình và tạo cặp mới với giá trị mới nhất của bên kia. Không cần ghép một-một nên nó chạy tới khi cả hai flow xong. Muốn có cặp ngay từ đầu, cho mỗi flow giá trị khởi đầu: `userUpdateFlow.onStart { emit(currentUser) }`. Dùng khi cần theo dõi hai nguồn thay đổi, ví dụ huy hiệu thông báo phụ thuộc cả trạng thái người dùng lẫn danh sách thông báo ([[src:kx-combine]]).', '`combine` also makes pairs and also waits for the slower side for the first pair. After that, every new element REPLACES its side\'s previous element and forms a new pair with the other side\'s latest value. It does not need one-to-one pairing, so it runs until both flows are done. To get a pair from the start, give each flow an initial value: `userUpdateFlow.onStart { emit(currentUser) }`. Use it to observe two sources of change, e.g. a notification badge that depends on both the user state and the notification list ([[src:kx-combine]]).')
    B(C, S, 4, 'kt', 'val flow1 = flowOf("A", "B", "C").onEach { delay(400) }\nval flow2 = flowOf(1, 2, 3, 4).onEach { delay(1000) }\n\nflow1.zip(flow2) { f1, f2 -> "${f1}_$f2" }.collect { println(it) }\n// (1 s) A_1 / (1 s) B_2 / (1 s) C_3\n\nflow1.combine(flow2) { f1, f2 -> "${f1}_$f2" }.collect { println(it) }\n// (1 s) B_1 / (0.2 s) C_1 / (0.8 s) C_2 / (1 s) C_3 / (1 s) C_4\n\nuserStateFlow\n    .combine(notificationsFlow) { userState, notifications ->\n        updateNotificationBadge(userState, notifications)\n    }\n    .collect()', 'val flow1 = flowOf("A", "B", "C").onEach { delay(400) }\nval flow2 = flowOf(1, 2, 3, 4).onEach { delay(1000) }\n\nflow1.zip(flow2) { f1, f2 -> "${f1}_$f2" }.collect { println(it) }\n// (1 s) A_1 / (1 s) B_2 / (1 s) C_3\n\nflow1.combine(flow2) { f1, f2 -> "${f1}_$f2" }.collect { println(it) }\n// (1 s) B_1 / (0.2 s) C_1 / (0.8 s) C_2 / (1 s) C_3 / (1 s) C_4\n\nuserStateFlow\n    .combine(notificationsFlow) { userState, notifications ->\n        updateNotificationBadge(userState, notifications)\n    }\n    .collect()')
    B(C, S, 5, 'predict', 'Với `combine` ở trên, vì sao kết quả đầu tiên là B_1 chứ không phải A_1?', 'With the `combine` above, why is the first result B_1 and not A_1?')
    B(C, S, 5, 'ans', 'A đến lúc 400 ms, B lúc 800 ms, còn số 1 tới lúc 1000 ms. Trước khi có cặp đầu, B đã thay A. Tới 1000 ms, giá trị mới nhất của flow1 là B nên ra B_1; A không bao giờ xuất hiện. Xem tab "combine" trong mô phỏng ngay sau phần flatMap.', 'A arrives at 400 ms, B at 800 ms, and 1 only at 1000 ms. Before the first pair exists, B has replaced A. At 1000 ms, flow1\'s latest value is B, so out comes B_1; A never appears. See the "combine" tab in the simulation right after the flatMap section.')

    S = 'flatmap'
    a(C + '.sec.%s.title' % S, 'flatMapConcat, flatMapMerge, flatMapLatest', 'flatMapConcat, flatMapMerge, flatMapLatest')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Với collection, `flatMap` biến mỗi phần tử thành một collection rồi làm phẳng (`departments.flatMap { it.employees }`). Với flow, mỗi phần tử biến thành một FLOW, và vì phần tử trải theo thời gian nên phải trả lời: flow con của phần tử thứ hai chờ flow con thứ nhất xong, hay chạy song song? Không có câu trả lời duy nhất, nên Flow không có `flatMap` mà có ba hàm: `flatMapConcat` (lần lượt), `flatMapMerge` (song song), `flatMapLatest` (chỉ giữ flow con mới nhất).', 'With collections, `flatMap` turns each element into a collection and flattens the result (`departments.flatMap { it.employees }`). With flows, each element becomes a FLOW, and since elements are spread over time you must answer: does the second element\'s child flow wait for the first, or run concurrently? There is no single answer, so Flow has no `flatMap` but three functions: `flatMapConcat` (one by one), `flatMapMerge` (concurrently), `flatMapLatest` (keep only the newest child).')
    B(C, S, 2, 'kt', 'fun flowFrom(elem: String) = flowOf(1, 2, 3)\n    .onEach { delay(1000) }\n    .map { "${it}_$elem" }\n\nflowOf("A", "B", "C").flatMapConcat { flowFrom(it) }   // 1_A 2_A 3_A 1_B … 3_C, mỗi giây một\nflowOf("A", "B", "C").flatMapMerge { flowFrom(it) }    // (1 s) 1_A 1_B 1_C (1 s) 2_A 2_B 2_C (1 s) 3_A 3_B 3_C\nflowOf("A", "B", "C").flatMapMerge(concurrency = 2) { flowFrom(it) }\n                                                       // A và B trước, C bắt đầu khi có chỗ (1_C ở giây thứ 4)\nflowOf("A", "B", "C").flatMapLatest { flowFrom(it) }   // không có delay ngoài: chỉ 1_C 2_C 3_C', 'fun flowFrom(elem: String) = flowOf(1, 2, 3)\n    .onEach { delay(1000) }\n    .map { "${it}_$elem" }\n\nflowOf("A", "B", "C").flatMapConcat { flowFrom(it) }   // 1_A 2_A 3_A 1_B … 3_C, one per second\nflowOf("A", "B", "C").flatMapMerge { flowFrom(it) }    // (1 s) 1_A 1_B 1_C (1 s) 2_A 2_B 2_C (1 s) 3_A 3_B 3_C\nflowOf("A", "B", "C").flatMapMerge(concurrency = 2) { flowFrom(it) }\n                                                       // A and B first, C starts when a slot frees (1_C at second 4)\nflowOf("A", "B", "C").flatMapLatest { flowFrom(it) }   // no outer delay: only 1_C 2_C 3_C')
    B(C, S, 3, 'p', '`concurrency` của `flatMapMerge` mặc định là 16 (đổi được trên JVM bằng thuộc tính `DEFAULT_CONCURRENCY_PROPERTY_NAME`). Coi chừng giới hạn này: với flow nhiều phần tử, chỉ 16 flow con chạy cùng lúc. Dùng điển hình: gọi API cho từng phần tử. So với `async` + `awaitAll`, `flatMapMerge` có hai lợi thế: chỉnh được số request đồng thời (tránh bắn hàng trăm request một lúc), và trả về `Flow` nên phần tử nào về trước thì xử lý trước ([[src:kx-flatmapmerge]]).', '`flatMapMerge`\'s `concurrency` defaults to 16 (changeable on the JVM with the `DEFAULT_CONCURRENCY_PROPERTY_NAME` property). Beware of this limit: with a flow of many elements, only 16 children run at the same time. Typical use: an API call per element. Compared with `async` + `awaitAll`, `flatMapMerge` has two advantages: you control how many requests run at once (instead of firing hundreds), and it returns a `Flow`, so whichever element arrives first is handled first ([[src:kx-flatmapmerge]]).')
    B(C, S, 4, 'kt', 'suspend fun getOffers(categories: List<Category>): List<Offer> = coroutineScope {\n    categories.map { async { api.requestOffers(it) } }.flatMap { it.await() }\n}\n\n// tốt hơn\nfun getOffers(categories: List<Category>): Flow<Offer> = categories\n    .asFlow()\n    .flatMapMerge(concurrency = 20) {\n        suspend { api.requestOffers(it) }.asFlow()   // hoặc flow { emit(api.requestOffers(it)) }\n    }', 'suspend fun getOffers(categories: List<Category>): List<Offer> = coroutineScope {\n    categories.map { async { api.requestOffers(it) } }.flatMap { it.await() }\n}\n\n// better\nfun getOffers(categories: List<Category>): Flow<Offer> = categories\n    .asFlow()\n    .flatMapMerge(concurrency = 20) {\n        suspend { api.requestOffers(it) }.asFlow()   // or flow { emit(api.requestOffers(it)) }\n    }')
    B(C, S, 5, 'p', '`flatMapLatest` quên flow con cũ ngay khi có phần tử mới. Thú vị nhất khi phần tử ngoài đến thưa: với `onEach { delay(1200) }`, A bắt đầu lúc 1,2 s và kịp phát 1_A lúc 2,2 s; B đến lúc 2,4 s nên flow của A bị đóng; B kịp phát 1_B; C đến và chạy trọn 1_C, 2_C, 3_C. Trên Android đây là mẫu tìm kiếm khi gõ: `queryFlow.flatMapLatest { q -> repo.search(q) }`, kết quả của truy vấn cũ không bao giờ đè lên kết quả mới ([[src:kx-flatmaplatest]]).', '`flatMapLatest` forgets the old child as soon as a new element appears. It is most interesting when outer elements are spaced out: with `onEach { delay(1200) }`, A starts at 1.2 s and manages to emit 1_A at 2.2 s; B arrives at 2.4 s so A\'s flow is closed; B manages to emit 1_B; C arrives and runs fully: 1_C, 2_C, 3_C. On Android this is the search-as-you-type pattern: `queryFlow.flatMapLatest { q -> repo.search(q) }`, so results for an old query never overwrite results for the new one ([[src:kx-flatmaplatest]]).')
    B(C, S, 6, 'predict', 'Với `flatMapMerge(concurrency = 2)` và ba phần tử A, B, C (mỗi flow con 3 giây), 1_C ra lúc nào? Toàn bộ xong lúc nào?', 'With `flatMapMerge(concurrency = 2)` and three elements A, B, C (each child takes 3 seconds), when does 1_C come out? When is everything done?')
    B(C, S, 6, 'ans', 'A và B chiếm hai chỗ tới giây thứ 3. C bắt đầu lúc 3 s nên 1_C ra lúc 4 s, và tất cả xong lúc 6 s (so với 3 s khi không giới hạn và 9 s với concat). Chạy chế độ đó trong mô phỏng ngay dưới để kiểm.', 'A and B hold both slots until second 3. C starts at 3 s, so 1_C comes out at 4 s, and everything is done at 6 s (versus 3 s with no limit and 9 s with concat). Run that mode in the simulation just below to check.')

    S = 'retry'
    a(C + '.sec.%s.title' % S, 'retry và retryWhen: chạy lại flow phía trên', 'retry and retryWhen: rerunning the upstream')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Exception chảy xuống và đóng từng tầng; tầng đã đóng không gửi tiếp được. Nhưng mỗi tầng giữ tham chiếu tới tầng phía trên, nên có thể collect lại từ đầu. `retryWhen { cause, attempt -> Boolean }` làm đúng vậy: khi có exception từ phía trên, hỏi predicate; `true` thì collect lại, `false` thì ném tiếp. `retry(retries) { cause -> Boolean }` là `retryWhen { cause, attempt -> attempt < retries && predicate(cause) }` ([[src:kx-retrywhen]]).', 'An exception flows down and closes each stage; a closed stage cannot send anything more. But each stage holds a reference to the one above, so it can collect again from the start. `retryWhen { cause, attempt -> Boolean }` does exactly that: on an exception from upstream it asks the predicate; `true` means collect again, `false` means rethrow. `retry(retries) { cause -> Boolean }` is `retryWhen { cause, attempt -> attempt < retries && predicate(cause) }` ([[src:kx-retrywhen]]).')
    B(C, S, 2, 'kt', '// retryWhen giản lược\nfun <T> Flow<T>.retryWhen(predicate: suspend FlowCollector<T>.(Throwable, Long) -> Boolean): Flow<T> = flow {\n    var attempt = 0L\n    do {\n        val shallRetry = try {\n            collect { emit(it) }\n            false\n        } catch (e: Throwable) {\n            predicate(e, attempt++).also { if (!it) throw e }\n        }\n    } while (shallRetry)\n}\n\nflow { emit(1); emit(2); error("E"); emit(3) }\n    .retry(3) { print(it.message); true }\n    .collect { print(it) }            // 12E12E12E12 (rồi exception bị ném)\n\nfun makeConnection(config: ConnectionConfig) = api.startConnection(config)\n    .retryWhen { e, attempt ->\n        delay(100 * attempt)                       // chờ tăng dần\n        log.error(e) { "Error for $config" }\n        e is ApiException && e.code !in 400..499   // không thử lại lỗi phía client\n    }', '// simplified retryWhen\nfun <T> Flow<T>.retryWhen(predicate: suspend FlowCollector<T>.(Throwable, Long) -> Boolean): Flow<T> = flow {\n    var attempt = 0L\n    do {\n        val shallRetry = try {\n            collect { emit(it) }\n            false\n        } catch (e: Throwable) {\n            predicate(e, attempt++).also { if (!it) throw e }\n        }\n    } while (shallRetry)\n}\n\nflow { emit(1); emit(2); error("E"); emit(3) }\n    .retry(3) { print(it.message); true }\n    .collect { print(it) }            // 12E12E12E12 (then the exception is thrown)\n\nfun makeConnection(config: ConnectionConfig) = api.startConnection(config)\n    .retryWhen { e, attempt ->\n        delay(100 * attempt)                       // increasing backoff\n        log.error(e) { "Error for $config" }\n        e is ApiException && e.code !in 400..499   // do not retry client errors\n    }')
    B(C, S, 3, 'ask', 'Trong output `12E12E12E12`, vì sao 1 và 2 được in bốn lần? Điều đó gây hậu quả gì cho người collect?', 'In the output `12E12E12E12`, why are 1 and 2 printed four times? What does that mean for the collector?')
    B(C, S, 3, 'ans', '`retry` collect LẠI flow phía trên từ đầu (lần đầu + 3 lần thử lại). Flow lạnh chạy lại toàn bộ khối builder, nên các phần tử đã phát trước lỗi được phát lần nữa. Người collect sẽ nhận trùng: nếu nó cộng dồn hay thêm vào danh sách, kết quả bị nhân đôi. Hoặc làm việc xử lý idempotent (thay vì cộng thêm), hoặc đặt `retry` sát nguồn có thể lỗi (ví dụ quanh một request đơn lẻ).', '`retry` collects the upstream AGAIN from the start (the first run + 3 retries). A cold flow reruns its whole builder block, so the elements emitted before the error are emitted again. The collector receives duplicates: if it sums or appends, results are doubled. Either make the handling idempotent (replace rather than add), or place `retry` right around the source that can fail (e.g. around a single request).')

    S = 'distinct'
    a(C + '.sec.%s.title' % S, 'distinctUntilChanged và các thao tác terminal', 'distinctUntilChanged and terminal operations')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', '`distinctUntilChanged()` bỏ phần tử bằng với phần tử NGAY TRƯỚC nó (không phải mọi phần tử đã thấy): `1, 2, 2, 3, 2, 1, 1, 3` → `1 2 3 2 1 3`. Biến thể: `distinctUntilChangedBy { it.id }` so theo khóa; `distinctUntilChanged { prev, next -> … }` tự định nghĩa "bằng nhau". Lưu ý: khi một phần tử bị bỏ, phần tử kế được so với phần tử ĐÃ PHÁT cuối cùng. `StateFlow` vốn đã bỏ giá trị trùng (so bằng `equals`), nên áp `distinctUntilChanged` lên `StateFlow` không có tác dụng ([[src:kx-stateflow]]).', '`distinctUntilChanged()` drops an element equal to the one RIGHT BEFORE it (not to every element seen): `1, 2, 2, 3, 2, 1, 1, 3` → `1 2 3 2 1 3`. Variants: `distinctUntilChangedBy { it.id }` compares by a key; `distinctUntilChanged { prev, next -> … }` defines "equal" yourself. Note: when an element is dropped, the next one is compared with the last EMITTED element. `StateFlow` already drops equal values (compared with `equals`), so applying `distinctUntilChanged` to a `StateFlow` has no effect ([[src:kx-stateflow]]).')
    B(C, S, 2, 'kt', 'fun <T> Flow<T>.distinctUntilChanged(): Flow<T> = flow {   // giản lược\n    var previous: Any? = NOT_SET\n    collect { if (previous == NOT_SET || previous != it) { emit(it); previous = it } }\n}\nprivate val NOT_SET = Any()\n\nval users = flowOf(User(1, "Alex"), User(1, "Bob"), User(2, "Bob"), User(2, "Celine"))\nusers.distinctUntilChangedBy { it.id }.toList()      // [[1] Alex, [2] Bob]\nusers.distinctUntilChangedBy { it.name }.toList()    // [[1] Alex, [1] Bob, [2] Celine]\nusers.distinctUntilChanged { p, n -> p.id == n.id || p.name == n.name }.toList()\n                                                     // [[1] Alex, [2] Bob]  ([2] Bob so với [1] Alex đã phát)\n\nval flow = flowOf(1, 2, 3, 4).map { it * it }\nflow.first()                              // 1\nflow.count()                              // 4\nflow.reduce { acc, v -> acc * v }         // 576\nflow.fold(0) { acc, v -> acc + v }        // 30\n\nsuspend fun Flow<Int>.sum(): Int { var sum = 0; collect { sum += it }; return sum }', 'fun <T> Flow<T>.distinctUntilChanged(): Flow<T> = flow {   // simplified\n    var previous: Any? = NOT_SET\n    collect { if (previous == NOT_SET || previous != it) { emit(it); previous = it } }\n}\nprivate val NOT_SET = Any()\n\nval users = flowOf(User(1, "Alex"), User(1, "Bob"), User(2, "Bob"), User(2, "Celine"))\nusers.distinctUntilChangedBy { it.id }.toList()      // [[1] Alex, [2] Bob]\nusers.distinctUntilChangedBy { it.name }.toList()    // [[1] Alex, [1] Bob, [2] Celine]\nusers.distinctUntilChanged { p, n -> p.id == n.id || p.name == n.name }.toList()\n                                                     // [[1] Alex, [2] Bob]  ([2] Bob compared with the emitted [1] Alex)\n\nval flow = flowOf(1, 2, 3, 4).map { it * it }\nflow.first()                              // 1\nflow.count()                              // 4\nflow.reduce { acc, v -> acc * v }         // 576\nflow.fold(0) { acc, v -> acc + v }        // 30\n\nsuspend fun Flow<Int>.sum(): Int { var sum = 0; collect { sum += it }; return sum }')
    B(C, S, 3, 'p', 'Thao tác terminal (`collect`, `first`, `firstOrNull`, `count`, `fold`, `reduce`, `toList`) là hàm suspend, trả kết quả khi flow xong (hoặc tự kết thúc flow như `first`). Hầu hết chỉ là một `collect` với lambda, nên bạn tự viết được terminal riêng như `sum` ở trên. Trong đoạn mã trên, bốn lần gọi terminal là bốn lần chạy lại flow lạnh: nếu nguồn là request mạng, bạn đã gửi bốn request.', 'Terminal operations (`collect`, `first`, `firstOrNull`, `count`, `fold`, `reduce`, `toList`) are suspending functions that return once the flow completes (or end the flow themselves, like `first`). Most are just a `collect` with a lambda, so you can write your own terminal like `sum` above. In the code above, the four terminal calls are four runs of the cold flow: if the source were a network request, you would have sent four requests.')

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp khi xử lý flow', 'Common bugs in flow processing')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', 'Ô tìm kiếm: gõ "kot" rồi "kotlin", màn hình hiện kết quả cho "kot" SAU kết quả cho "kotlin" (đôi khi đè mất).', 'A search box: type "kot" then "kotlin", and the screen shows results for "kot" AFTER the results for "kotlin" (sometimes overwriting them).')
    B(C, S, 1, 'cause', 'Dùng `flatMapMerge` (hoặc `launch` riêng cho mỗi truy vấn): các request chạy song song và về theo thứ tự bất kỳ. Request cho "kot" chậm hơn nên về sau.', 'Using `flatMapMerge` (or a separate `launch` per query): requests run in parallel and return in any order. The "kot" request was slower, so it came back later.')
    B(C, S, 1, 'fix', '`flatMapLatest`: truy vấn mới hủy request cũ. Thường thêm `debounce(300)` và `distinctUntilChanged()` trước đó để không gọi khi người dùng còn đang gõ.', '`flatMapLatest`: a new query cancels the old request. Usually add `debounce(300)` and `distinctUntilChanged()` before it so you do not call while the user is still typing.')
    B(C, S, 1, 'fixkt', 'queryFlow\n    .debounce(300)\n    .distinctUntilChanged()\n    .flatMapLatest { q -> repo.search(q) }\n    .onEach { render(it) }\n    .launchIn(viewModelScope)')
    B(C, S, 2, 'bug', 'Màn hình chi tiết `combine(userFlow, settingsFlow) { … }` đứng ở trạng thái loading mãi.', 'A detail screen with `combine(userFlow, settingsFlow) { … }` stays in the loading state forever.')
    B(C, S, 2, 'cause', '`combine` chỉ phát khi MỖI flow đã có ít nhất một giá trị. `settingsFlow` là luồng sự kiện chỉ phát khi người dùng đổi cài đặt, nên chưa bao giờ có cặp đầu tiên.', '`combine` only emits once EVERY flow has at least one value. `settingsFlow` is an event stream that only emits when the user changes a setting, so the first pair never forms.')
    B(C, S, 2, 'fix', 'Cho flow đó giá trị khởi đầu: `settingsFlow.onStart { emit(currentSettings) }`, hoặc biến nó thành `StateFlow` (luôn có giá trị).', 'Give that flow an initial value: `settingsFlow.onStart { emit(currentSettings) }`, or make it a `StateFlow` (which always has a value).')
    B(C, S, 3, 'bug', 'Tổng tiền giỏ hàng thỉnh thoảng gấp đôi sau khi mạng chập chờn.', 'The cart total occasionally doubles after a flaky network.')
    B(C, S, 3, 'cause', 'Chuỗi `itemsFlow().retry(3).collect { total += it.price }`: khi lỗi giữa chừng, `retry` collect lại từ đầu nên các món đầu được phát lại và cộng thêm lần nữa.', 'The chain `itemsFlow().retry(3).collect { total += it.price }`: on a mid-stream failure, `retry` collects again from the start, so the first items are emitted again and added again.')
    B(C, S, 3, 'fix', 'Đừng giữ trạng thái cộng dồn ngoài flow. Tính bằng thao tác terminal trên một lần chạy thành công (`retry` quanh request, rồi `fold`), hoặc dùng `scan`/thay thế thay vì cộng thêm.', 'Do not keep accumulated state outside the flow. Compute it with a terminal operation over one successful run (`retry` around the request, then `fold`), or use `scan`/replace instead of adding.')

